/**
 * Fail-open rules fetch (frozen contract v1): total budget 2000ms, one retry
 * with jitter, any failure resolves to EMPTY_RULESET plus exactly one warning.
 * A rules fetch can never fail or delay a customer run beyond the budget.
 */

import type { ActionCondition, ActionRule, ActionRulesetV1, RunGitContext } from './types.js';
import { EMPTY_RULESET } from './types.js';
import type { Logger } from '../utils/logger.js';

export const ACTIONS_RULES_PATH = '/api/v1/actions/rules';

const TOTAL_BUDGET_MS = 2000;
const FIRST_ATTEMPT_MS = 900;
const RETRY_DELAY_BASE_MS = 100;
const RETRY_DELAY_JITTER_MS = 200;
const MAX_RULES = 500;

const VALID_ACTIONS = new Set(['skip', 'quarantine', 'tag']);

export interface FetchActionRulesOptions {
  token: string;
  serverUrl: string;
  git?: RunGitContext;
  logger?: Logger;
}

export async function fetchActionRules(options: FetchActionRulesOptions): Promise<ActionRulesetV1> {
  const deadline = Date.now() + TOTAL_BUDGET_MS;
  const url = buildRulesUrl(options.serverUrl, options.git);

  const failOpen = (reason: string): ActionRulesetV1 => {
    options.logger?.warn(`TestDino Actions: rules fetch failed - running without rules (${reason})`);
    return EMPTY_RULESET;
  };

  let first: FetchAttemptResult;
  try {
    first = await attemptFetch(url, options.token, Math.min(FIRST_ATTEMPT_MS, deadline - Date.now()));
  } catch (error) {
    first = { ok: false, reason: describeError(error) };
  }
  if (first.ok) return first.ruleset;

  const delay = RETRY_DELAY_BASE_MS + Math.random() * RETRY_DELAY_JITTER_MS;
  if (Date.now() + delay >= deadline) return failOpen(first.reason);
  await sleep(delay);

  let second: FetchAttemptResult;
  try {
    second = await attemptFetch(url, options.token, deadline - Date.now());
  } catch (error) {
    second = { ok: false, reason: describeError(error) };
  }
  if (second.ok) return second.ruleset;
  return failOpen(second.reason);
}

type FetchAttemptResult = { ok: true; ruleset: ActionRulesetV1 } | { ok: false; reason: string };

async function attemptFetch(url: string, token: string, timeoutMs: number): Promise<FetchAttemptResult> {
  if (timeoutMs <= 0) return { ok: false, reason: 'timeout' };

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  timer.unref?.();

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${token}`,
        'x-td-actions-contract': '1',
      },
      signal: controller.signal,
    });

    if (response.status !== 200) {
      return { ok: false, reason: `HTTP ${response.status}` };
    }

    let body: unknown;
    try {
      body = await response.json();
    } catch {
      return { ok: false, reason: 'invalid JSON response' };
    }

    const ruleset = parseActionRuleset(body);
    if (!ruleset) {
      return { ok: false, reason: 'unsupported response shape or contract version' };
    }
    return { ok: true, ruleset };
  } catch (error) {
    if (controller.signal.aborted) return { ok: false, reason: 'timeout' };
    return { ok: false, reason: describeError(error) };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Validates and sanitizes a raw ruleset. Returns null when the envelope is not
 * contract v1. Malformed rules are dropped whole (dropping a single condition
 * would broaden the rule's match, which is never safe).
 */
export function parseActionRuleset(raw: unknown): ActionRulesetV1 | null {
  if (raw === null || typeof raw !== 'object') return null;
  const data = raw as Record<string, unknown>;
  if (data.contractVersion !== 1) return null;
  if (!Array.isArray(data.rules)) return null;

  const rules: ActionRule[] = [];
  for (const candidate of data.rules.slice(0, MAX_RULES)) {
    const rule = sanitizeRule(candidate);
    if (rule) rules.push(rule);
  }

  return {
    contractVersion: 1,
    fetchedAt: typeof data.fetchedAt === 'string' ? data.fetchedAt : new Date().toISOString(),
    rules,
  };
}

function sanitizeRule(raw: unknown): ActionRule | null {
  if (raw === null || typeof raw !== 'object') return null;
  const data = raw as Record<string, unknown>;

  if (typeof data.id !== 'string' || data.id.length === 0) return null;
  if (typeof data.name !== 'string') return null;
  if (typeof data.action !== 'string' || !VALID_ACTIONS.has(data.action)) return null;
  if (!Array.isArray(data.conditions) || data.conditions.length === 0) return null;

  const tagValue = typeof data.tagValue === 'string' && data.tagValue.length > 0 ? data.tagValue : undefined;
  // A tag rule without a tag value can never do anything — treat as malformed.
  if (data.action === 'tag' && !tagValue) return null;

  const conditions: ActionCondition[] = [];
  for (const candidate of data.conditions) {
    const condition = sanitizeCondition(candidate);
    if (!condition) return null;
    conditions.push(condition);
  }

  return {
    id: data.id,
    name: data.name,
    action: data.action as ActionRule['action'],
    ...(tagValue !== undefined && { tagValue }),
    expiresAt: typeof data.expiresAt === 'string' ? data.expiresAt : '',
    conditions,
  };
}

function sanitizeCondition(raw: unknown): ActionCondition | null {
  if (raw === null || typeof raw !== 'object') return null;
  const data = raw as Record<string, unknown>;

  if (typeof data.field !== 'string' || data.field.length === 0) return null;
  if (typeof data.operator !== 'string' || data.operator.length === 0) return null;
  if (!Array.isArray(data.values) || !data.values.every((v): v is string => typeof v === 'string')) return null;

  return {
    field: data.field,
    operator: data.operator,
    values: data.values,
    isRegex: data.isRegex === true,
  };
}

function buildRulesUrl(serverUrl: string, git?: RunGitContext): string {
  const base = serverUrl.replace(/\/+$/, '');
  const params = new URLSearchParams();
  if (git?.branch) params.set('branch', git.branch);
  if (git?.authorEmail) params.set('commitAuthorEmail', git.authorEmail);
  const query = params.toString();
  return `${base}${ACTIONS_RULES_PATH}${query ? `?${query}` : ''}`;
}

function describeError(error: unknown): string {
  if (error instanceof Error) {
    if (error.name === 'AbortError') return 'timeout';
    return error.message;
  }
  return String(error);
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => {
    const timer = setTimeout(resolve, ms);
    timer.unref?.();
  });
}
