/**
 * Pure rule matcher implementing the frozen v1 semantics (phases doc, 2026-08-12).
 * A condition's field resolves to string[] (undefined = absent); conditions AND
 * within a rule. Unknown field or operator evaluates false — a client must never
 * fire a rule it does not understand.
 */

import type { ActionCondition, ActionRule, TestMatchContext } from './types.js';

export const MAX_MATCH_INPUT_LEN = 10_000;
export const MAX_REGEX_PATTERN_LEN = 512;

const KNOWN_FIELDS = new Set([
  'file',
  'title',
  'titlePath',
  'testId',
  'tags',
  'project',
  'errorMessage',
  'gitBranch',
  'gitAuthorEmail',
  'gitAuthorName',
  'gitMessage',
  'gitRemote',
]);

export function matchRule(rule: ActionRule, ctx: TestMatchContext): boolean {
  // A rule with zero conditions would match everything — refuse to fire it.
  if (rule.conditions.length === 0) return false;
  return rule.conditions.every((condition) => matchCondition(condition, ctx));
}

/** A rule is pre-test matchable when no condition needs the test's error output. */
export function isPreTestMatchable(rule: ActionRule): boolean {
  return rule.conditions.every((condition) => condition.field !== 'errorMessage');
}

export function matchCondition(condition: ActionCondition, ctx: TestMatchContext): boolean {
  if (!KNOWN_FIELDS.has(condition.field)) return false;

  const resolved = resolveField(condition.field, ctx);

  switch (condition.operator) {
    case 'missing':
      return resolved === undefined;
    case 'missingAny':
      return resolved === undefined || resolved.length === 0;
    case 'isEmpty':
      return resolved !== undefined && resolved.length === 0;
    case 'is':
      return matchesSingle(resolved, condition);
    case 'isNot':
      return !matchesSingle(resolved, condition);
    case 'isAny':
    case 'in':
      return matchesSome(resolved, condition);
    case 'notIn':
      return !matchesSome(resolved, condition);
    case 'includes':
      return matchesEvery(resolved, condition);
    case 'includesSome':
      return matchesSome(resolved, condition);
    default:
      return false;
  }
}

/** Resolves a condition field to its list form. undefined = field absent. */
export function resolveField(field: string, ctx: TestMatchContext): string[] | undefined {
  switch (field) {
    case 'file':
      return scalar(ctx.file);
    case 'title':
      return scalar(ctx.title);
    case 'titlePath':
      return ctx.titlePath;
    case 'testId':
      return scalar(ctx.testId);
    case 'tags':
      return ctx.tags;
    case 'project':
      return scalar(ctx.project);
    case 'errorMessage':
      return scalar(ctx.errorMessage);
    case 'gitBranch':
      return scalar(ctx.git?.branch);
    case 'gitAuthorEmail':
      return scalar(ctx.git?.authorEmail);
    case 'gitAuthorName':
      return scalar(ctx.git?.authorName);
    case 'gitMessage':
      return scalar(ctx.git?.message);
    case 'gitRemote':
      return scalar(ctx.git?.remote);
    default:
      return undefined;
  }
}

function scalar(value: string | undefined): string[] | undefined {
  return value === undefined ? undefined : [value];
}

/** is/isNot: single value (values[0]); some element equals/regex-matches it. */
function matchesSingle(resolved: string[] | undefined, condition: ActionCondition): boolean {
  if (!resolved || condition.values.length === 0) return false;
  const value = condition.values[0];
  return resolved.some((element) => valueMatches(element, value, condition.isRegex));
}

/** isAny/in/includesSome: some value matched by some element. */
function matchesSome(resolved: string[] | undefined, condition: ActionCondition): boolean {
  if (!resolved || condition.values.length === 0) return false;
  return condition.values.some((value) => resolved.some((element) => valueMatches(element, value, condition.isRegex)));
}

/** includes: EVERY value matched by some element (all-of). */
function matchesEvery(resolved: string[] | undefined, condition: ActionCondition): boolean {
  if (!resolved || condition.values.length === 0) return false;
  return condition.values.every((value) => resolved.some((element) => valueMatches(element, value, condition.isRegex)));
}

function valueMatches(element: string, value: string, isRegex: boolean): boolean {
  if (!isRegex) return element === value;
  if (value.length > MAX_REGEX_PATTERN_LEN) return false;
  // Bounded input so a pathological pattern cannot hang customer CI.
  const input = element.length > MAX_MATCH_INPUT_LEN ? element.slice(0, MAX_MATCH_INPUT_LEN) : element;
  try {
    return new RegExp(value).test(input);
  } catch {
    return false;
  }
}
