/**
 * Compiles pre-test skip rules into a Playwright --grep-invert pattern.
 *
 * Playwright's grep target is the space-joined title path INCLUDING the file
 * path, with tags appended — so `$` anchoring is unsafe and every literal is an
 * unanchored substring (`^` only for a full-titlePath `is`). Rules that cannot
 * ride grep (negative/zero-arity operators, project/testId conditions) do not
 * compile — a documented limitation; those rules remain in the ruleset for the
 * reporter.
 */

import { isPreTestMatchable, matchCondition, MAX_REGEX_PATTERN_LEN } from './matcher.js';
import type { ActionCondition, ActionRule, RunGitContext } from './types.js';

const GIT_FIELDS = new Set(['gitBranch', 'gitAuthorEmail', 'gitAuthorName', 'gitMessage', 'gitRemote']);
const GREP_FIELDS = new Set(['title', 'titlePath', 'file', 'tags']);
const POSITIVE_OPERATORS = new Set(['is', 'isAny', 'in', 'includes', 'includesSome']);

export function escapeRegex(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Always merges — never replaces a user-supplied pattern. */
export function mergeGrepInvert(user: string | undefined, ours: string): string {
  return user ? `(${user})|(${ours})` : ours;
}

export interface ExtractedGrepInvert {
  args: string[];
  pattern?: string;
}

// Only the long spellings: Playwright has no -gv short flag (it would parse
// those tokens as positional file filters, so consuming them here would
// silently reinterpret the user's arguments).
export function extractGrepInvert(args: string[]): ExtractedGrepInvert {
  const rest: string[] = [];
  let pattern: string | undefined;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--grep-invert') {
      if (i + 1 < args.length) {
        pattern = args[i + 1];
        i++;
      }
      continue;
    }
    if (arg.startsWith('--grep-invert=')) {
      pattern = arg.slice('--grep-invert='.length);
      continue;
    }
    rest.push(arg);
  }

  return { args: rest, ...(pattern !== undefined && { pattern }) };
}

/**
 * Returns the OR-joined pattern of every compilable skip rule, or undefined
 * when nothing compiles. Git conditions are evaluated NOW against runCtx:
 * all pass → the rule compiles (its grep conditions form the pattern);
 * any fail → the rule is dropped for this run.
 */
export function compileSkipInvertPattern(rules: ActionRule[], runCtx: RunGitContext): string | undefined {
  const rulePatterns: string[] = [];

  for (const rule of rules) {
    if (rule.action !== 'skip' || !isPreTestMatchable(rule) || rule.conditions.length === 0) continue;
    const pattern = compileRule(rule, runCtx);
    if (pattern !== undefined) rulePatterns.push(pattern);
  }

  if (rulePatterns.length === 0) return undefined;
  if (rulePatterns.length === 1) return rulePatterns[0];
  return rulePatterns.map((p) => `(?:${p})`).join('|');
}

interface Fragment {
  source: string;
  anchored: boolean;
}

function compileRule(rule: ActionRule, runCtx: RunGitContext): string | undefined {
  const fragments: Fragment[] = [];

  for (const condition of rule.conditions) {
    if (GIT_FIELDS.has(condition.field)) {
      if (!matchCondition(condition, { git: runCtx })) return undefined;
      continue;
    }
    if (!GREP_FIELDS.has(condition.field) || !POSITIVE_OPERATORS.has(condition.operator)) return undefined;

    const conditionFragments = compileCondition(condition);
    if (conditionFragments === undefined) return undefined;
    fragments.push(...conditionFragments);
  }

  return combineFragments(fragments);
}

function compileCondition(condition: ActionCondition): Fragment[] | undefined {
  if (condition.values.length === 0) return undefined;

  const pieces: string[] = [];
  for (const value of condition.values) {
    const piece = compileValuePattern(value, condition.isRegex);
    if (piece === undefined) return undefined;
    pieces.push(piece);
  }

  // `^` anchor only for full-titlePath `is`; everything else is a substring.
  const anchored = condition.field === 'titlePath' && condition.operator === 'is';

  switch (condition.operator) {
    case 'is':
      return [{ source: pieces[0], anchored }];
    case 'isAny':
    case 'in':
    case 'includesSome':
      return [{ source: pieces.length === 1 ? pieces[0] : `(?:${pieces.join('|')})`, anchored: false }];
    case 'includes':
      // all-of: every value becomes its own AND-ed fragment.
      return pieces.map((source) => ({ source, anchored: false }));
    default:
      return undefined;
  }
}

function compileValuePattern(value: string, isRegex: boolean): string | undefined {
  if (!isRegex) return escapeRegex(value);
  if (value.length > MAX_REGEX_PATTERN_LEN) return undefined;
  try {
    new RegExp(value);
  } catch {
    return undefined;
  }
  // Grouped so alternation/precedence inside the value cannot leak out.
  return `(?:${value})`;
}

function combineFragments(fragments: Fragment[]): string {
  // Only git conditions (all passed) — the rule matches every test this run.
  if (fragments.length === 0) return '.*';
  if (fragments.length === 1) {
    const f = fragments[0];
    return f.anchored ? `^${f.source}` : f.source;
  }
  // Multi-condition AND via lookaheads: ^(?=.*A)(?=.*B)
  return `^${fragments.map((f) => (f.anchored ? `(?=${f.source})` : `(?=.*${f.source})`)).join('')}`;
}
