/**
 * TestDino Actions — wire contract v1 types (frozen 2026-08-12).
 * Rules are fetched once at run start by the CLI, embedded in the temp config,
 * and evaluated client-side (matcher.ts owns all matching semantics).
 */

export type ActionRuleAction = 'skip' | 'quarantine' | 'tag';

export interface ActionCondition {
  field: string;
  operator: string;
  values: string[];
  isRegex: boolean;
}

export interface ActionRule {
  id: string;
  name: string;
  action: ActionRuleAction;
  tagValue?: string;
  expiresAt: string;
  conditions: ActionCondition[];
}

export interface ActionRulesetV1 {
  contractVersion: 1;
  fetchedAt: string;
  rules: ActionRule[];
}

/** Run-level git context collected once by the CLI at run start. */
export interface RunGitContext {
  branch?: string;
  authorEmail?: string;
  authorName?: string;
  message?: string;
  remote?: string;
}

/** Per-test matching input. errorMessage is only available post-test (final attempt). */
export interface TestMatchContext {
  file?: string;
  title?: string;
  titlePath?: string[];
  testId?: string;
  tags?: string[];
  project?: string;
  errorMessage?: string;
  git?: RunGitContext;
}

export const EMPTY_RULESET: ActionRulesetV1 = Object.freeze({
  contractVersion: 1,
  fetchedAt: '',
  rules: [],
});
